  var esc = function(s){ return String(s || '').trim().replace(/'/g, "\\'").toLowerCase(); };
  var v = esc($fromAI('session_type', 'The session type exactly as it appears in Airtable - one of: Band Recording, Celebrity Recording, Event, Localization Atmos Mixing, Localization Dubbing, Localization Editing, Localization Mixing, Meeting, Music Mixing, Music Vocal Recording, Post Mixing, QC, VO Recording. Never abbreviate.', 'string', ''));
  if (!v) { throw new Error('Give the session type. Nothing was looked up.'); }
  return "OR(LOWER({Type}) = '" + v + "', SEARCH('" + v + "', LOWER({Type})))";
})() }}

={{ (function(){
  var esc  = function(s){ return String(s || '').trim().replace(/'/g, "\\'"); };
  var room = esc($fromAI('room_name', 'Exact room name, only when the requester named one - e.g. "Studio 4". Empty otherwise.', 'string', ''));
  var fmt  = esc($fromAI('recording_format', 'The audio format asked about: Stereo, Stereo with Sub, 5.1, Atmos, or None. Use this for any question about what a room can record or mix in.', 'string', ''));
  var kind = esc($fromAI('room_kind', 'The kind of room, when that is what was asked: Editing, Recording Control Room, Stereo Mixing, 5.1 Mixing, M Booth, Recording Booth, Conference Room, Atmos Suite, Color Grading, Video Editing, Lobby, Van. This is a category, not a capability.', 'string', ''));
  var st   = esc($fromAI('runs_session_type', 'A session type, to find the rooms it is run in. Empty otherwise.', 'string', ''));
  var vb   = $fromAI('vocal_booth', 'True only when asked which rooms are vocal booths.', 'boolean', false);
  var parts = ['{Active / Bookable}'];
  if (room) parts.push("{Room Name} = '" + room + "'");
  if (fmt)  parts.push("FIND('" + fmt + "', ARRAYJOIN({Recording Format}))");
  if (kind) parts.push("FIND('" + kind + "', ARRAYJOIN({Room Type}))");
  if (st)   parts.push("OR(FIND('" + st + "', ARRAYJOIN({Session Types})), FIND('" + st + "', ARRAYJOIN({Session Types 2})))");
  if (vb === true || String(vb).toLowerCase() === 'true') parts.push('{Vocal Booth}');
  if (parts.length === 1) { throw new Error('Say what you are looking for: a room name, a recording format, a kind of room, a session type, or vocal booths. Nothing was looked up.'); }
  return 'AND(' + parts.join(', ') + ')';
})() }}

